"""Build the five-screen, plan-aware Garmin advisor as one private HTML file."""
from __future__ import annotations

import json
import math
import os
import statistics
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

from advisor_engine import decide, match_week, measured, median_or_none, planned_sessions

ROOT = Path(__file__).resolve().parent
DATA_DIR = Path(os.environ.get("GARMIN_DATA_DIR", ROOT / "data"))
OUT = ROOT / "dashboard.html"
INDIA_TIME = timezone(timedelta(hours=5, minutes=30))
TODAY = datetime.now(INDIA_TIME).date()


def load(name, default):
    try:
        path = DATA_DIR / name
        if not path.exists():
            path = ROOT / name
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return default


def as_date(value):
    try:
        return datetime.strptime(str(value)[:10], "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


def nested(value, *keys):
    for key in keys:
        if not isinstance(value, dict):
            return None
        value = value.get(key)
    return value


def avg(values):
    values = [value for item in values if (value := measured(item)) is not None]
    return statistics.fmean(values) if values else None


def pearson(pairs):
    if len(pairs) < 7:
        return None
    xs, ys = zip(*pairs)
    xm, ym = avg(xs), avg(ys)
    denominator = math.sqrt(sum((x-xm)**2 for x in xs) * sum((y-ym)**2 for y in ys))
    return sum((x-xm)*(y-ym) for x, y in pairs) / denominator if denominator else None


def linear_slope(pairs):
    if len(pairs) < 7:
        return None
    xs, ys = zip(*pairs)
    xm, ym = avg(xs), avg(ys)
    denominator = sum((x-xm)**2 for x in xs)
    return sum((x-xm)*(y-ym) for x, y in pairs) / denominator if denominator else None


def normalize_activity(item):
    activity_type = item.get("activityType") or {}
    key = str(activity_type.get("typeKey") if isinstance(activity_type, dict) else activity_type).lower()
    start = str(item.get("startTimeLocal") or "")
    km = (measured(item.get("distance")) or 0) / 1000
    duration_min = (measured(item.get("duration")) or 0) / 60
    zones = [measured(item.get(f"hrTimeInZone_{index}")) or 0 for index in range(1, 6)]
    return {
        "id": str(item.get("activityId") or item.get("uuid") or start), "date": start[:10], "start": start,
        "name": item.get("activityName") or key.replace("_", " ").title(), "type": key,
        "km": round(km, 2), "durationMin": round(duration_min, 1), "avgHr": measured(item.get("averageHR")),
        "load": measured(item.get("activityTrainingLoad")), "pace": round(duration_min/km, 2) if km and "running" in key else None,
        "zones": zones, "temp": measured(item.get("averageTemperature")),
        "cadence": measured(item.get("averageRunningCadenceInStepsPerMinute")),
        "groundContact": measured(item.get("avgGroundContactTime")), "strideCm": measured(item.get("avgStrideLength")),
        "verticalOsc": measured(item.get("avgVerticalOscillation")), "verticalRatio": measured(item.get("avgVerticalRatio")),
    }


def adjusted_pace_window(runs, start, end, target_hr):
    rows = [run for run in runs if start <= as_date(run["date"]) <= end and run.get("avgHr") and run.get("pace")]
    if len(rows) < 4:
        return None, len(rows)
    xs = [row["avgHr"] for row in rows]
    ys = [row["pace"] for row in rows]
    xm, ym = avg(xs), avg(ys)
    denominator = sum((x-xm)**2 for x in xs)
    slope = sum((x-xm)*(y-ym) for x, y in zip(xs, ys))/denominator if denominator else 0
    return ym + slope*(target_hr-xm), len(rows)


def old_week_history(activities):
    monday = TODAY - timedelta(days=TODAY.weekday())
    rows = []
    for offset in range(15, -1, -1):
        start = monday - timedelta(weeks=offset)
        end = start + timedelta(days=6)
        group = [a for a in activities if start <= as_date(a["date"]) <= end]
        rows.append({"start": start.isoformat(), "end": end.isoformat(), "rangeLabel": f"{start:%d %b}–{end:%d %b}", "current": offset == 0, "score": None, "effect": "Plan adherence", "sessions": len(group), "km": round(sum(a["km"] for a in group), 1), "load": round(sum(a["load"] or 0 for a in group)), "recovery": None, "remainingRecovery": None, "days": []})
    return rows


def build():
    raw_activities = load("activities.json", [])
    activities = [normalize_activity(item) for item in raw_activities]
    daily, sleep, hrv = {}, {}, {}
    for item in load("daily_summaries.json", []):
        day = as_date(item.get("calendarDate"))
        if not day:
            continue
        daily[day] = {
            "rhr": measured(nested(item, "heartRate", "restingValue")), "hrMin": measured(nested(item, "heartRate", "minValue")),
            "hrMax": measured(nested(item, "heartRate", "maxValue")), "stress": measured(nested(item, "stress", "avgLevel")),
            "steps": measured(nested(item, "movement", "steps", "value")), "stepGoal": measured(nested(item, "movement", "steps", "goal")),
            "bodyBattery": measured(nested(item, "bodyBattery", "latestValue")), "bodyBatteryMax": measured(nested(item, "bodyBattery", "maxValue")),
        }
    for item in load("sleep.json", []):
        day = as_date(item.get("calendarDate")); seconds = measured(item.get("sleepTimeSeconds"))
        if day and seconds:
            sleep[day] = {"hours": seconds/3600, "score": measured(nested(item, "sleepScores", "overall", "value")), "needMin": measured(nested(item, "sleepNeed", "actual")), "startMs": measured(item.get("sleepStartTimestampLocal")), "deep": (measured(item.get("deepSleepSeconds")) or 0)/3600, "rem": (measured(item.get("remSleepSeconds")) or 0)/3600}
    for item in load("hrv.json", []):
        day = as_date(item.get("calendarDate"))
        if day:
            hrv[day] = {"night": measured(item.get("lastNightAvg")), "weekly": measured(item.get("weeklyAvg")), "status": str(item.get("status") or "").replace("_", " ").title(), "low": measured(nested(item, "baseline", "balancedLow")), "high": measured(nested(item, "baseline", "balancedUpper"))}

    weights = []
    for item in load("weight.json", []):
        latest = item.get("latestWeight") or {}; day = as_date(item.get("summaryDate") or latest.get("calendarDate")); grams = measured(latest.get("weight"))
        if day and grams: weights.append({"d": day.isoformat(), "v": round(grams/1000, 2)})
    weights.sort(key=lambda row: row["d"])
    fitness = load("fitness_age.json", {}); plan = load("routine.json", {}); refresh = load("refresh_status.json", {})
    try: refresh_display = datetime.fromisoformat(refresh.get("last_success", "")).strftime("%d %b, %I:%M %p")
    except (TypeError, ValueError): refresh_display = "Not refreshed"

    rhr_baseline = median_or_none(daily.get(TODAY-timedelta(days=index), {}).get("rhr") for index in range(1, 31))
    current_day = daily.get(TODAY, {}); latest_sleep_day = max((day for day in sleep if day <= TODAY), default=None); latest_hrv_day = max((day for day in hrv if day <= TODAY), default=None)
    current_sleep = sleep.get(latest_sleep_day, {}); current_hrv = hrv.get(latest_hrv_day, {})
    sleep_need = (current_sleep.get("needMin")/60) if current_sleep.get("needMin") else avg(row.get("hours") for day, row in sleep.items() if TODAY-timedelta(days=7) <= day <= TODAY)
    rhr_partial = bool(current_day.get("rhr") is not None and current_day.get("hrMin") == current_day.get("hrMax") == current_day.get("rhr"))
    today_metrics = {"rhr": current_day.get("rhr"), "hrv": current_hrv.get("night") if latest_hrv_day == TODAY else None, "sleep_h": current_sleep.get("hours"), "stress": current_day.get("stress"), "rhr_partial": rhr_partial}
    baselines = {"rhr_30d_median": rhr_baseline, "hrv_balanced_low": current_hrv.get("low"), "hrv_balanced_high": current_hrv.get("high"), "sleep_need_h": sleep_need}
    today_plan = planned_sessions(plan, TODAY); default_decision = decide(today_metrics, baselines, {}, today_plan)

    monday = TODAY - timedelta(days=TODAY.weekday()); plan_weeks = []
    for offset in range(15, -1, -1):
        start = monday - timedelta(weeks=offset); matched = match_week(plan, raw_activities, start, TODAY)
        matched["start"] = start.isoformat(); matched["rangeLabel"] = f"{start:%d %b}–{start+timedelta(days=6):%d %b}"; matched["current"] = offset == 0; plan_weeks.append(matched)
    current_week = plan_weeks[-1]
    active_weeks = [row for row in plan_weeks if row["active"]]
    adherence_window = active_weeks[-4:]
    rolling_done = sum(row["done"] for row in adherence_window)
    rolling_planned = sum(row["planned"] for row in adherence_window)
    adherence4 = round(rolling_done/rolling_planned*100) if rolling_planned else None
    adherence_weeks = len(adherence_window)
    history = old_week_history(activities); weeks = [{"d": row["start"], "label": row["rangeLabel"].split("–")[0], "distance": row["km"], "load": row["load"], "hours": round(sum(a["durationMin"] for a in activities if row["start"] <= a["date"] <= row["end"])/60, 2), "sessions": row["sessions"]} for row in history]

    outdoor_runs = [a for a in activities if a["type"] in {"running", "trail_running"} and a.get("pace") and a.get("avgHr")]
    recent_pace, recent_n = adjusted_pace_window(outdoor_runs, TODAY-timedelta(days=44), TODAY, 150); prior_pace, prior_n = adjusted_pace_window(outdoor_runs, TODAY-timedelta(days=89), TODAY-timedelta(days=45), 150)
    same_hr = {"targetHr": 150, "recentPace": recent_pace, "priorPace": prior_pace, "recentN": recent_n, "priorN": prior_n, "enough": recent_n >= 4 and prior_n >= 4, "note": "Outdoor runs only. Temperature is shown when Garmin recorded it; treadmill runs are excluded."}
    long_runs = sorted([a for a in outdoor_runs if a["km"] >= 4], key=lambda row: row["date"])[-12:]
    sleep_rhr_pairs = [(sleep[day]["hours"], daily[day]["rhr"]) for day in sleep.keys() & daily.keys() if daily[day].get("rhr") is not None]
    stress_sleep_pairs = [(daily[day]["stress"], sleep[day+timedelta(days=1)]["score"]) for day in daily if daily[day].get("stress") is not None and day+timedelta(days=1) in sleep and sleep[day+timedelta(days=1)].get("score") is not None]
    bedtime_pairs = []
    for day, row in sleep.items():
        if row.get("startMs") and row.get("hours"):
            dt = datetime.fromtimestamp(row["startMs"]/1000); bedtime_pairs.append((dt.hour*60+dt.minute+(0 if dt.hour >= 18 else 1440), row["hours"]))
    sleep_rhr_slope = linear_slope(sleep_rhr_pairs)
    stress_sleep_slope = linear_slope(stress_sleep_pairs)
    bedtime_slope = linear_slope(bedtime_pairs)
    patterns = [
        {"title": "Sleep → resting HR", "r": pearson(sleep_rhr_pairs), "n": len(sleep_rhr_pairs), "effect": f"Nights with 1 hour more sleep were paired with resting HR about {abs(sleep_rhr_slope):.1f} bpm {'lower' if sleep_rhr_slope < 0 else 'higher'}." if sleep_rhr_slope is not None else "Not enough matched nights for an effect estimate.", "action": "Protect sleep and confirm the signal with HRV before changing training."},
        {"title": "Daytime stress → sleep", "r": pearson(stress_sleep_pairs), "n": len(stress_sleep_pairs), "effect": f"A 10-point higher daytime stress level was paired with a sleep score about {abs(stress_sleep_slope*10):.1f} points {'lower' if stress_sleep_slope < 0 else 'higher'}." if stress_sleep_slope is not None else "Not enough matched days for an effect estimate.", "action": "On high-stress days, use a repeatable 20-minute wind-down."},
        {"title": "Bedtime → sleep duration", "r": pearson(bedtime_pairs), "n": len(bedtime_pairs), "effect": f"Going to bed 1 hour later was paired with about {abs(bedtime_slope*3600):.0f} minutes {'less' if bedtime_slope < 0 else 'more'} sleep." if bedtime_slope is not None else "Not enough nights for an effect estimate.", "action": "Run a two-week earlier-lights-out experiment and compare the 7-day average."},
    ]
    missing_today = list(default_decision["missingInputs"]); missing_today += ["stress"] if current_day.get("stress") is None else []
    coverage = {"activities": len(activities), "dailyDays": len(daily), "sleepNights": len(sleep), "hrvNights": len(hrv), "weightEntries": len(weights), "missingToday": list(dict.fromkeys(missing_today))}
    series = lambda source, key: [{"d": day.isoformat(), "v": row[key]} for day, row in sorted(source.items()) if row.get(key) is not None and day >= TODAY-timedelta(days=364)]
    payload = {"today": TODAY.isoformat(), "plan": plan, "planWeeks": plan_weeks, "currentWeek": current_week, "adherence4": adherence4, "adherenceWeeks": adherence_weeks, "current": {"daily": current_day, "sleep": current_sleep, "sleepDate": latest_sleep_day.isoformat() if latest_sleep_day else None, "hrv": current_hrv, "hrvDate": latest_hrv_day.isoformat() if latest_hrv_day else None, "rhrPartial": rhr_partial, "rhrSource": "daily_summaries.heartRate.restingValue"}, "baselines": baselines, "defaultDecision": default_decision, "todayPlan": today_plan, "activities": activities, "weights": weights, "fitnessAge": fitness, "sameHrPace": same_hr, "longRuns": long_runs, "patterns": patterns, "coverage": coverage, "refreshDisplay": refresh_display, "weeks": weeks, "weekHistory": history, "rhr": series(daily, "rhr"), "hrv": series(hrv, "night"), "sleep": [{"d": day.isoformat(), "v": row["hours"], "deep": row["deep"], "rem": row["rem"], "score": row["score"]} for day, row in sorted(sleep.items()) if day >= TODAY-timedelta(days=364)], "sleepScore": series(sleep, "score"), "bodyBattery": series(daily, "bodyBattery"), "stress": series(daily, "stress"), "spo2": [], "efficiency": [], "weight": weights}
    page = TEMPLATE.replace("__DATA__", json.dumps(payload,separators=(",", ":")).replace("</", "<\\/"))
    page = page.replace("</style>", (ROOT / "advisor_v2.css").read_text(encoding="utf-8") + "\n</style>", 1)
    page = page.replace("</script>", (ROOT / "advisor_v2.js").read_text(encoding="utf-8") + "\n</script>", 1)
    OUT.write_text(page, encoding="utf-8")
    print(f"Advisor dashboard built: {OUT}")


